function generateBuildings() {
  buildings = [];

  // Scale factor based on canvas size (using min dimension for consistency)
  let baseSize = max(width, height);
  let nScale = baseSize / 600; // Reference size was 600

  // Generate random buildings with scaled coordinates
  let gridSpacing = 40 * nScale;
  let xStart = 0;
  let xEnd = 200 * nScale;
  let zStart = -20 * nScale;
  let zEnd = 400 * nScale;

  for (let x = xStart; x <= xEnd; x += (Math.max(0.001, Math.abs(gridSpacing)) || 1)) {
    for (let z = zStart; z <= zEnd; z += (Math.max(0.001, Math.abs(gridSpacing)) || 1)) {
      if (random() > 0.5) { // Some randomness in placement
        let buildingHeight = random(20 * nScale, 80 * nScale);
        let buildingWidth = random(20 * nScale, 35 * nScale);
        let buildingDepth = random(20 * nScale, 35 * nScale);

        // Random offsets for top vertices to create skewed buildings
        let maxSkew = 5 * nScale; // Maximum skew amount

        // Random window type: 0 = solid, 1 = horizontal stripes, 2 = grid, 3 = rectangles
        let windowType = random() > 0.2 ? random([1, 2, 3]) : 0; // 20% chance of solid

        // Pick two colors from palette for this building
        let mainColorIdx = floor(random(paletteHSB.length));
        let windowColorIdx = floor(random(paletteHSB.length));
        // Ensure they're different
        let _wG_1 = 0; while ((windowColorIdx === mainColorIdx && paletteHSB.length > 1) && ++_wG_1 < 20000) {
          windowColorIdx = floor(random(paletteHSB.length));
        }

        buildings.push({
          pos: createVector(x, 0, z),
          w: buildingWidth,
          h: buildingHeight,
          d: buildingDepth,
          windowType: windowType,
          mainColor: paletteHSB[mainColorIdx],
          windowColor: paletteHSB[windowColorIdx],
          topOffsets: {
            frontLeft: { x: random(-maxSkew, maxSkew), z: random(-maxSkew, maxSkew) },
            frontRight: { x: random(-maxSkew, maxSkew), z: random(-maxSkew, maxSkew) },
            backRight: { x: random(-maxSkew, maxSkew), z: random(-maxSkew, maxSkew) },
            backLeft: { x: random(-maxSkew, maxSkew), z: random(-maxSkew, maxSkew) }
          }
        });
      }
    }
  }
}

async function setup() {
  let canvas = createCanvas(windowWidth, windowHeight, WEBGL);
  rg = rough.canvas(canvas.elt);

  // Pick a random palette and convert to HSB
  selectedPalette = random(palettes);
  colorMode(RGB, 255);
  paletteHSB = selectedPalette.map(hex => {
    let c = color(hex);
    let h = hue(window.color(c));
    let s = saturation(window.color(c));
    let b = brightness(window.color(c));
    // Handle grayscale colors (saturation 0) - set hue to 0 since it's undefined
    if (isNaN(h) || s === 0) {
      h = 0;
    }
    return {
      h: h,
      s: s,
      b: b
    };
  });

  // Set color mode to HSB
  colorMode(HSB, 360, 100, 100);

  // Randomly decide if it's day or night
  isNight = random() > 0.5;

  // Create bright, desaturated background color from palette
  let bgSourceColor = random(selectedPalette);
  bgColor = chroma(bgSourceColor).desaturate(random(1, 2)).brighten(random(0.5, 2)).hex();

  generateBuildings();
}

